function longestEvenStretch(results) {
  const first = new Map([[0, -1]])
  let balance = 0
  let best = 0
  for (let i = 0; i < results.length; i++) {
    balance += results[i] === 'W' ? 1 : -1
    if (first.has(balance)) best = Math.max(best, i - first.get(balance))
    else first.set(balance, i)
  }
  return best
}

