def longest_even_stretch(results):
    first = {0: -1}
    balance = 0
    best = 0
    for i, result in enumerate(results):
        balance += 1 if result == 'W' else -1
        if balance in first:
            best = max(best, i - first[balance])
        else:
            first[balance] = i
    return best
